// Deferral-channel conformance (LLP 0001 async attribution). The dependency
// stamps the CPED slot (one op with a live frame), then schedules a DETACHED,
// frame-less privileged op (a bound-native Deno.env.get) through every deferral
// channel. Each callback runs with no evil-dep frame on the stack, so it is
// attributed only if that channel carried the CPED scheduling principal. If any
// channel drops the principal, its read attributes to no-user and the spec's
// expected 6th line is missing -> the test fails. That is the "reviewer memory
// converted to CI" guard: a new or regressed channel is caught.
import process from "node:process";
import { AsyncResource } from "node:async_hooks";

export function leak() {
  Deno.env.get("STAMP"); // stamp CPED = evil-dep (precedence row 1)
  const g = Deno.env.get.bind(null, "SECRET"); // bound native -> frame-less

  setTimeout(g, 0); // 1 web timer
  queueMicrotask(g); // 2 microtask
  Promise.resolve().then(g); // 3 promise reaction
  process.nextTick(g); // 4 node nextTick
  setImmediate(g); // 5 node setImmediate

  const ar = new AsyncResource("oden-test"); // 6 AsyncResource across a timer
  setTimeout(() => ar.runInAsyncScope(g), 0);
}
